INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorLBM', 'm17605 XVAL-LBM-AVERAGE-SURROUND-INIT', 17625, 3, $json${"os": "board-audit m17625 of m17605 (anchor XVAL-LBM-AVERAGE-SURROUND-INIT, repo TensorLBM, worktree /root/tp-agent/work/m17605, branch agent/m17605, commit 65631dec on top of c05d7af3); audit artifacts under docs/board_audit/m17625 + runs/m17625_audit", "impl_files": ["src/tensorlbm/free_surface_init_modes.py:1-311 (neighbour_average:163-197, birth_population:199-256, average_surround_reference:258-311, mode registry:53-97)", "src/tensorlbm/free_surface_lbm_2d.py:221-258 (_init_new_2d init_mode), :309-339 (_address_interface_layer envelope site), :630-657 (conversion site, DEAD: to_iface never set), :693-728 (free_surface_step_2d forwards init_mode)", "docs/XVAL_AVERAGE_SURROUND_INIT.md:1-224 (six-section XVAL report)"], "entry": "experiments/xval_average_surround_init/run_xval.py:1-475 (run_dam_break:225-270; main sweep:359-370) + make_tables.py:1-110", "run_artifacts": ["experiments/xval_average_surround_init/artifacts/xval_results.json (13665 B, 567 lines; operator_cases 4, sensitivity 3+4, solver_runs 5)", "experiments/xval_average_surround_init/artifacts/xval_tables.md (54 lines, generated by make_tables.py)", "experiments/xval_average_surround_init/artifacts/xval_ref_vs_got.png (120207 B)", "experiments/xval_average_surround_init/artifacts/xval_run.log (56 lines)", "runs/m17625_audit/repro_run.log + verify_m17605.json (this audit's independent rerun: physics payload byte-identical, runtime_s only)"], "tests": "tests/test_free_surface_init_modes_xval.py 14 tests; audit rerun 14 passed in 8.13 s (runs/m17625_audit/pytest_xval.log). Covers oracle parity, literal OSS-body port, D3Q19 stencil symmetry, active-neighbour filter, isolated fallback, typo rejection, threshold contrast, bit-identical pre-patch replica (rho_init None/1.0/0.7), step-level forwarding.", "integration_callers": {"wired": "koerner_step_2d / free_surface_step_2d / _address_interface_layer accept init_mode (legacy default); real 32x64 dam break reaches the birth path 6 times (run_xval.py:249-260 counting wrapper)", "production_callers_using_new_mode": "none: lng_sloshing/tank.py:337, lng_membrane_sloshing/campaign.py:194, nwt/tank.py:341, sloshing_forced/* call koerner_step_2d without init_mode => default legacy", "measurement": "32x64 dam break legacy vs average_surround |Δf|∞ = 0.0 (bit-identical), front/inventory diff 0.000%", "why_inert": "the only live birth site (envelope shell) already averaged neighbours before this patch; the conversion site that would change behaviour (free_surface_lbm_2d.py:630) is dead code because to_iface is all-False at the call"}, "benchmark": {"registered_case": "none: SELECT ... FROM tensor_benchmark_cases WHERE anchor_slug='XVAL-LBM-AVERAGE-SURROUND-INIT' -> 0 rows (table total 55; TensorLBM anchors are GAP-LBM-MCMP-POISEUILLE / GAP-LBM-SPHERE / H2-FRAZIL-RHEOLOGY / CASE-LBM-SQUARE-CYL-NORBERG only)", "ref_source": "in-mission float64 transcription of Maarten-vd-Sande/lbm@573a01c average_surround (BOTH ref implementations authored by m17605) => not an independent numeric reference", "operator_ref_vs_got": {"C1_homogeneous": {"ref_rho": 1.0, "avg_rel_f": 2.4e-08, "fixed_rel_f": 2.4e-08}, "C2_pressure_gradient": {"ref_rho": 1.002, "avg_rel_f": 2.4e-07, "fixed_rel_f": 0.002}, "C3_density_contrast": {"ref_rho": 1.3, "avg_rel_f": 4.66e-08, "fixed_rel_f": 0.2308}, "C4_multiphase_like": {"ref_rho": 0.5, "avg_rel_f": 2.43e-08, "fixed_rel_f": 1.0}, "gate": "15 %: average_surround passes all 4, fixed_rho fails C3/C4"}, "system_level": "front/inventory divergence across modes = 0.000% (average_surround) and 1.04e-03 |Δf|∞ (fixed_rho) at 32x64; 64x128 has 0 births in the 80-step window => no birth evidence at that grid", "verdict": "benchmark judgement WITHHELD: no registered ref/tolerance row; the discriminating evidence is a synthetic operator patch, not a full application case"}, "repro_cmd": "cd /root/tp-agent/work/m17605 && PYTHONPATH=src python -m pytest tests/test_free_surface_init_modes_xval.py -q  # 14 passed; PYTHONPATH=src python experiments/xval_average_surround_init/run_xval.py  # 18.3 s, VERDICT operator 2.399e-07 PASS / fixed 1.000e+00 FAIL (audit rerun in a throw-away copy, physics payload identical)", "external_anchor": "Maarten-vd-Sande/lbm @573a01c lbm/update_types.py:135-160 (average_surround) + call site :42-48, verified byte-for-byte in /root/oss-cache/Maarten-vd-Sande_lbm (git log -1 = 573a01c). REAL external source anchor (source-level only: no OSS executable output was compared)", "independent_checks": {"third_party_oss_loop": "audit-written NumPy implementation of the OSS body vs torch kernel: max rel population diff 4.05e-16 over 24 random fields; module oracle gap 0.0", "legacy_bit_identity": "sha256 of (f,mass,flags) at steps 1/10/30/60 of a 32x64 dam break identical to pristine pre-patch tree /root/tp-agent/work/m17457 (file sha256 4254488f... == c05d7af3) => True; fixed_rho differs at 32x64", "doc_numbers": "all 4 operator rows, 3 velocity + 4 density sensitivity rows, 5 system rows and the verdict numbers re-derived from xval_results.json: 0 discrepancy", "report_six_sections": "tensor_reports id=16565 (13531 chars) has all six required sections"}, "level_rationale": "L3: L1/L2 met (real operator module + oracle + 14 tests incl. literal OSS port and bit-identical regression), L3 met (init_mode threaded into the main 2D free-surface solver API and exercised by 6 real births in a dam break). L4 NOT met: tensor_benchmark_cases has 0 rows for the anchor, the numeric ref is an in-mission transcription of OSS semantics (no independent OSS run or third-party result), and the system-level complete case shows 0 divergence because the discriminating birth site is dead code.", "findings": {"F1_no_registered_benchmark": "0 rows in tensor_benchmark_cases for the anchor => benchmark judgement withheld; L4 not confirmable by the sole arbiter (non-blocking for L3).", "F2_level_overstated": "m17605 result headline/server_quality_audit claim 'L0 -> L4' (gate_valid=false, key_present=false); audited level is L3 — the L4 claim rests on a self-authored ref and a synthetic patch.", "F3_capability_inert_in_solver": "average_surround is bit-identical to legacy in the live 2D solver: envelope births already averaged, conversion site (free_surface_lbm_2d.py:630) is dead code; no production caller selects the mode. The new capability is testable but not behaviour-changing today.", "F4_one_sided_discrimination": "the only case where fixed_rho fails the 15 % gate (C3/C4, 23 %/100 %) is a synthetic density-contrast patch; the pressure-matched dam break cannot exceed 0.2 % — reported honestly by m17605.", "F5_stale_runtime_metadata": "xval_tables.md / verdict.runtime_s says 14.0 s (committed) vs 18.3 s on audit rerun; metadata only, physics payload identical.", "F6_documented_deviations": "isolated-cell fallback (OSS rho=0 empty population vs rho_liquid) and mass-ledger (OSS mass=0) are deliberate and test-pinned; audit's independent OSS loop reproduces both sides."}, "report": "tensor_reports id=16565 (m17605 original, six sections) / this audit's report posted by m17625", "artifacts": ["docs/board_audit/m17625/verify_m17605.py (8-phase independent verification)", "runs/m17625_audit/verify_m17605.json (per-check evidence)", "runs/m17625_audit/repro_run.log, pytest_xval.log, bitid_dam_break.py", "runs/m17625_audit/m17625_audit_figure.png", "docs/board_audit/m17625/AUDIT_M17605.md"]}$json$::jsonb, 'board-audit') ON CONFLICT (repo, scope, verdict_by) DO UPDATE SET level=EXCLUDED.level, evidence=EXCLUDED.evidence, mission_id=EXCLUDED.mission_id, gate_state='pending', gate_level=NULL, gate_note=NULL RETURNING id, gate_state, level;